(function(root){
 'use strict';
 const C=root.SiaLearningCore,E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let bridge;
 const profile=()=>bridge.getProfile(),parent=()=>bridge.isParent?.()===true;
 function changeBands(p,fields){for(const area of ['ko','en','play'])if(fields.has('band:'+area))C.setBand(p,area,fields.get('band:'+area));}
 function init(api){bridge=api;C.state(profile());
  document.addEventListener('change',e=>{if(!e.target.matches('[data-parent-band]')||!parent())return;const form=e.target.form,p=JSON.parse(JSON.stringify(profile()));changeBands(p,new FormData(form));form.querySelectorAll('[data-domain]').forEach(s=>{s.value=C.level(p,s.dataset.domain,s.dataset.language);});});
  document.addEventListener('submit',e=>{if(e.target.id!=='learning-level-form')return;e.preventDefault();if(!parent())return;const p=profile(),before=JSON.stringify(p),fields=new FormData(e.target);changeBands(p,fields);
   e.target.querySelectorAll('[data-domain]').forEach(s=>C.manual(p,s.dataset.domain,s.dataset.language,Number(s.value)));
   if(bridge.saveProfile()){bridge.toast('나이 묶음과 레벨을 저장했어요. 다음 활동부터 적용돼요.');bridge.render?.();}else Object.assign(p,JSON.parse(before));
  });
  document.addEventListener('click',e=>{const b=e.target.closest('[data-band-suggestion]');if(!b||!parent())return;const p=profile(),before=JSON.stringify(p),t=C.state(p).tracks[b.dataset.bandSuggestion],s=t?.suggestBandUp;if(!s)return;if(b.dataset.accept==='yes'){C.setBand(p,C.areaOf(s.domain,s.lang),s.to);C.track(p,s.domain,s.lang,1);}delete t.suggestBandUp;if(bridge.saveProfile())bridge.render?.();else Object.assign(p,JSON.parse(before));});
 }
 const level=(domain,lang)=>C.level(profile(),domain,lang),start=(domain,id,options)=>C.start(profile(),domain,id,options);
 function select(domain,lang,value){if(!parent())return false;const before=JSON.stringify(C.state(profile()));C.manual(profile(),domain,lang,value);if(bridge.saveProfile())return true;profile().learningProgress=JSON.parse(before);return false;}
 function respond(attempt,mood,metrics){const before=JSON.stringify(C.state(profile())),previous=JSON.stringify(attempt),result=C.respond(profile(),attempt,mood,metrics);if(!result)return null;if(!bridge.saveProfile()){profile().learningProgress=JSON.parse(before);for(const key of Object.keys(attempt))delete attempt[key];Object.assign(attempt,JSON.parse(previous));return null;}return result;}
 function message(r){if(!r)return '';return ({easier:'다음엔 조금 더 편하게 해 보자.',harder:'다음엔 한 단계 더 도전해 보자!',just:'좋아! 다음에도 이만큼 해 보자.',minimum:'천천히 해도 괜찮아. 하루와 같이 해 보자.',maximum:'레벨 5 완성! 가장 높은 단계까지 해냈어.','band-up':'레벨 5 완성! 다음 묶음은 부모님과 정해 보자.',practice:'한 번 더 익숙해진 뒤 도전해 보자.',parent:'부모님과 답을 확인하면 다음 레벨에 반영할게.',newer:'느낌을 기억했어. 다음에는 지금 맞춘 레벨로 만나자.'})[r.reason]||'';}
 function feedbackHtml(a){return '<div class="learning-feedback"><h2>어땠어?</h2><div class="learning-feelings">'+[['hard','😅'],['just','🙂'],['easy','😎']].map(([v,emoji])=>'<button type="button" data-learning-feedback="'+v+'" aria-pressed="'+(a?.feedback===v)+'" '+(a?.feedback?'disabled':'')+'><span aria-hidden="true">'+emoji+'</span>'+C.MOODS[v]+'</button>').join('')+'</div><p class="learning-feedback-result" role="status">'+E(message(a?.adjustment))+'</p></div>';}
 function bandText(domain,lang=profile().lang,p=profile()){const area=C.areaOf(domain,lang);return C.BAND_LABEL[C.bandFor(p,area)]+(C.bandOverridden(p,area)?' · 부모님이 고른 묶음':'');}
 function bandChip(domain,lang){return '<span class="learning-band-readonly">'+E(bandText(domain,lang))+'</span>';}
 function bandSelect(area,p=profile()){const natural=C.ageBand(p.age||7),o=p.bandOverride?.[area],selected=o?.forBand===natural?o.band:'auto';return '<select name="band:'+area+'" data-parent-band aria-label="'+({ko:'한글',en:'영어',play:'놀이'}[area])+' 나이 묶음"><option value="auto" '+(selected==='auto'?'selected':'')+'>나이에 맞춤 ('+C.BAND_LABEL[natural]+')</option>'+C.BANDS.map(b=>'<option value="'+b+'" '+(selected===b?'selected':'')+'>'+C.BAND_LABEL[b]+(b===natural?'':C.BASE[b]<C.BASE[natural]?' (부모님이 낮춤)':' (부모님이 올림)')+'</option>').join('')+'</select>';}
 function bandFieldset(){return '<fieldset class="learning-band-settings"><legend>나이 묶음</legend><div class="form-row">'+['ko','en','play'].map(a=>'<label>'+({ko:'한글',en:'영어',play:'놀이'}[a])+bandSelect(a)+'</label>').join('')+'</div><p>낱말 조립·이야기 탐정·별빛 문장 우체국·말풍선 극장은 한글/영어 묶음을 따라요. 나이 묶음이 바뀌는 생일에는 나이에 맞춤으로 돌아갑니다.</p></fieldset>';}
 function levelSelect(id,lang){return '<select name="'+lang+':'+id+'" data-domain="'+id+'" data-language="'+lang+'" aria-label="'+C.TRACKS[id].title+' '+(lang==='en'?'영어':'한글')+' 레벨">'+[1,2,3,4,5].map(n=>'<option value="'+n+'" '+(level(id,lang)===n?'selected':'')+'>레벨 '+n+'</option>').join('')+'</select>';}
 function parentSummary(){const p=profile(),progress=C.state(p),history=progress.history.slice(-6).reverse();
  const suggestions=Object.entries(progress.tracks).filter(([,t])=>t.suggestBandUp&&C.bandOf(p,t.suggestBandUp.domain,t.suggestBandUp.lang)===t.suggestBandUp.from).map(([key,t])=>{const s=t.suggestBandUp;return '<div class="learning-band-suggestion"><p>‘'+E(C.TRACKS[s.domain].title)+'’ '+C.BAND_LABEL[s.from]+' 레벨 5를 쉽게 해냈어요. '+C.BAND_LABEL[s.to]+' 묶음으로 올려 볼까요?</p><button type="button" class="btn primary" data-band-suggestion="'+E(key)+'" data-accept="yes">올리기</button> <button type="button" class="btn outline" data-band-suggestion="'+E(key)+'" data-accept="no">나중에</button></div>';}).join('');
  return '<section class="learning-parent-card"><h2>아이에게 맞춰 가는 레벨</h2><p>나이 묶음 안에서 레벨 1부터 시작해요. 이야기와 그리기는 언어·묶음별로, 놀이는 게임·묶음별로 기억해요.</p>'+suggestions+'<form id="learning-level-form">'+bandFieldset()+'<div class="learning-level-table"><div class="learning-level-row learning-level-heading"><span>활동</span><span>한글</span><span>영어</span></div>'+Object.entries(C.TRACKS).filter(([id])=>C.available(p,id)&&(id!=='library'||Number(p.age)<8)).map(([id,t])=>'<div class="learning-level-row"><strong>'+t.title+'</strong>'+(C.isGame(id)?'<label class="learning-shared-level">'+levelSelect(id,p.lang||'ko')+'<small>게임별 공통</small></label>':['ko','en'].map(l=>levelSelect(id,l)).join(''))+'</div>').join('')+'</div><button class="btn primary" type="submit">묶음·레벨 저장</button></form><p class="learning-parent-note">‘어려웠어’는 한 단계 내리고 ‘딱 좋아’는 유지해요. ‘쉬웠어’는 이야기 첫 답 80% 이상 또는 놀이 별 2개 이상일 때 한 단계 올려요. 화석 발굴은 첫 퀴즈 정답도 필요해요. 레벨 5 다음 묶음은 부모님만 정할 수 있어요.</p>'+(p.age>=8&&p.readingPreferences?.en==='together'?'<p>영어가 처음이라면 부모님 공간에서 영어 묶음을 낮출 수 있어요.</p>':'')+(history.length?'<details class="learning-history"><summary>최근 느낌과 조절 기록</summary>'+history.map(r=>'<p><b>'+E(r.title)+'</b> · '+E(C.BAND_LABEL[r.band]||'이전 기록')+' · '+C.MOODS[r.feedback]+'<br><span>레벨 '+r.from+(r.to!==r.from?' → '+r.to:' 유지')+' · '+E(message(r))+'</span></p>').join('')+'</details>':'')+'</section>';
 }
 root.SiaLearning={init,level,start,select,respond,feedbackHtml,bandText,bandChip,bandSelect,message,parentSummary,core:C,profile};
})(window);

